import { useState } from 'preact/hooks';
import ArrowForwardIcon from '@material-ui/icons/ArrowForward';

import Popover from '../../../../../shared/Popover';
import Button from '../../../../../shared/Button';

import styles from './styles.module.scss';
import { FunctionComponent } from 'preact';

const STEPS = [
  {
    title: 'Add your friends and see how many bottles they recover',
    src:
      'https://assets.oceanhero.today/extension/friends/friends-onboarding-1.mp4',
    submit: 'Nice!',
  },
  {
    title: 'Keep each other motivated by sending funny GIF’s',
    src:
      'https://assets.oceanhero.today/extension/friends/friends-onboarding-2.mp4',
    submit: 'Super nice!',
  },
];

interface Props {
  onFinished: () => unknown,
  onClose: () => unknown,
}

const Onboarding: FunctionComponent<Props> = ({ onFinished, onClose }: Props) => {
  const [index, setIndex] = useState(0);
  const step = STEPS[index];

  const handleSubmit = () => {
    if (index >= STEPS.length - 1) return onFinished();
    setIndex(index + 1);
  };

  return (
    <Popover onClose={onClose} className={styles.onboardingPopover}>
      <h2 className={styles.title}>{step.title}</h2>
      <video
        src={step.src}
        className={styles.video}
        loop
        muted
        autoPlay
      />
      {/* <img className={styles.image} src={step.img} alt="" /> */}
      <Button size="large" variant="primary" onClick={handleSubmit}>
        {step.submit} <ArrowForwardIcon />
      </Button>
    </Popover>
  );
};

export default Onboarding;
